mapper.select:
SELECT
    id, event_id, recipient_reference, ticket_id, notification_type,
    message, created_at, read_at
FROM ticket_notification
WHERE id = #{notificationId}
  AND recipient_reference = #{recipientReference}

mapper.update:
UPDATE ticket_notification
SET read_at = #{readAt}
WHERE id = #{notificationId}
  AND recipient_reference = #{recipientReference}
  AND read_at IS NULL
